<?php
 namespace ehr; require_once(__DIR__ . '/../../../../init.php'); require_once(__DIR__ . '/../autoload.php'); interface iResourceItemMan extends iResourceItem { } abstract class ResourceItemMan extends ResourceItem implements iResourceItemMan { protected const LINK_ATTR_RELATEDPERSON = 'RelatedPerson'; protected const MSG_ERROR_RELATEDPRESON = 'Ухаживающий за пациентом', MSG_ERROR_PATIENT = 'Пациент', MSG_ERROR_DOCTOR = 'Врач', MSG_ERROR_NOTREGISTERED = 'не имеет регистрации в ЦОД'; protected $surName; protected $name; protected $secondName; protected $fio; protected $pin; protected $errorPersonalNumber; public function __construct(Resource $aResource) { parent::__construct($aResource); } public function __destruct() { parent::__destruct(); } public function getFio(): string { return $this->fio; } public function getPIN(): string { return $this->pin; } public function setPIN(string $pin): void { $this->pin = $pin; } public function initData(array $record): void { parent::initData($record); $this->surName = $record['surname']; $this->name = $record['name']; $this->secondName = $record['secondName']; $this->fio = "{$record['surname']} {$record['name']} {$record['secondName']}"; $this->guid = $record['guid'] ?? ''; $this->pin = $record['personalNumber'] ?? ''; $this->errorPersonalNumber = $record['errorPersonalNumber']; } protected function &addFIONode(\stdClass &$node): \stdClass { $name = &LinkJSON::addNode($node, 'name'); LinkJSON::addNode($name, 'use', 'official'); LinkJSON::addNodeEx($name, 'family', [$this->surName]); LinkJSON::addNodeEx($name, 'given', $this->name); LinkJSON::addNodeEx($name, 'given', $this->secondName); return $name; } public function clearResourceItem(): void { parent::clearResourceItem(); $this->name = ''; $this->surName = ''; $this->secondName = ''; $this->fio = ''; $this->pin = ''; } private function addReferenceRelatedPerson(\stdClass &$node, string $name): void { if (empty($this->getId())) { return; } if (empty($this->getGUID())) { throw new Exception($this->makeReferenceErrorMessage(self::MSG_ERROR_RELATEDPERSON)); } $this->addSubReference($node, $name, self::LINK_ATTR_RELATEDPERSON); } private function makeReferenceErrorMessage(string $aString = ''): string { return "{$this->getManForErrorMsg($aString)} " . self::MSG_ERROR_NOTREGISTERED; } private function getManForErrorMsg(string $aPrefix = ''): string { $resource = $this->getResource(); switch ($resource->getSource()) { case self::ITEM_SOURCE_SICKLIST_RELATEDPERSON: $prefix = self::MSG_ERROR_OTHER; break; case self::ITEM_SOURCE_RECIPE_PATIENT: $prefix = self::MSG_ERROR_PATIENT; break; case self::ITEM_SOURCE_RECIPE_PRATITIONER: $prefix = self::MSG_ERROR_DOCTOR; break; default: $prefix = $aPrefix; break; } return $prefix . (empty($prefix) ? '' : ' ') . "{$this->getFIO()}, {$resource->getFieldName()}={$this->getId()}"; } } 